import{_ as a,c as o,o as t,a1 as r}from"./chunks/framework.C3Hmo1as.js";const _=JSON.parse('{"title":"Claude Code 使用心得","description":null,"frontmatter":{"title":"Claude Code 使用心得","description":null,"date":"2026-04-17T00:00:00.000Z","tags":["Claude Code"]},"headers":[],"relativePath":"ai/claude-code.md","filePath":"ai/claude-code.md"}'),l={name:"ai/claude-code.md"};function d(c,e,i,n,s,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="clear" tabindex="-1"><code>/clear</code> <a class="header-anchor" href="#clear" aria-label="Permalink to &quot;`/clear`&quot;">​</a></h2><ul><li><p>在使用 Claude Code（以及 Cursor、Aider 等各种基于 LLM 的编程工具）时，在进行<strong>不同功能的修改之间使用 <code>/clear</code> 清空上下文，是一个极其优秀且被广泛推荐的工程习惯。</strong></p></li><li><p>这能带来三大核心优势：</p></li></ul><h3 id="_1-大幅减少-token-消耗" tabindex="-1">1. 大幅减少 Token 消耗 <a class="header-anchor" href="#_1-大幅减少-token-消耗" aria-label="Permalink to &quot;1. 大幅减少 Token 消耗&quot;">​</a></h3><p>大语言模型是“无状态”的，为了保持对话连贯，每一次你发送新消息，工具都会把你之前的全部对话历史打包重新发送给大模型。如果你做了几个功能还不清理上下文，那些已经解决的、包含大量代码的旧对话会呈指数级消耗 Token。及时 <code>/clear</code> 可以避免为无关的冗长历史买单。</p><h3 id="_2-有效降低幻觉-防止上下文污染" tabindex="-1">2. 有效降低幻觉（防止上下文污染） <a class="header-anchor" href="#_2-有效降低幻觉-防止上下文污染" aria-label="Permalink to &quot;2. 有效降低幻觉（防止上下文污染）&quot;">​</a></h3><p>如果上一个任务是“编写后端 SQLite 查询”，下一个任务是“调整前端 CSS 动画”，如果不清空，AI 的注意力会被之前后端相关的代码分散。它可能会在写前端代码时，莫名其妙地带入后端逻辑，或者错误地复用上一个任务中的变量名。这就是“上下文污染”导致的幻觉。清空后，等于给了 AI 一个干净的白板。</p><h3 id="_3-提升专注度与指令执行力" tabindex="-1">3. 提升专注度与指令执行力 <a class="header-anchor" href="#_3-提升专注度与指令执行力" aria-label="Permalink to &quot;3. 提升专注度与指令执行力&quot;">​</a></h3><p>上下文越短、越纯粹，模型对当前 Prompt（比如你刚才要提供给它的那些带有“保留注释”等严格约束的提示词）的权重分配就越高。在一个极其干净的环境下，AI 严格遵守复杂指令的成功率会大幅提升，因为它不需要在海量旧信息中去抓取当前的重点。</p><ul><li><strong>唯一不需要 <code>/clear</code> 的场景：</strong> 只有当你的新任务<strong>强依赖</strong>于刚完成的任务时（例如：“在刚刚写好的那个 SQL 语句基础上，再加一个 GROUP BY 条件”），才应该保留上下文。一旦开启全新的独立功能模块，果断清空是最佳策略。</li></ul><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2>',10)])])}const p=a(l,[["render",d]]);export{_ as __pageData,p as default};
